<?php $this->layout('default'); use Moves\Services\CmsAuth; use Moves\Services\PlatformBilling as B; use Moves\Support\CmsView as V;
$filters = ['q' => V::queryString('q'), 'status' => V::queryString('status')]; $result = B::subscriptions($filters, V::queryPage());
$plans = []; foreach (B::plans() as $p) { if ($p['status'] === 'active' && $p['price_id']) { $plans[$p['id']] = $p['name']; } } ?>
<?php if (CmsAuth::can($admin, 'subscriptions.manage')): ?><details class="cms-card"><summary>Nova assinatura</summary><form method="post" action="/acao/subscription-create"><?= V::csrf() ?><div class="cms-form-grid"><?= V::field('E-mail do assinante', 'owner_email', '', ['type' => 'email', 'help' => 'Para pessoa física.']) ?><?= V::field('ID da empresa', 'organization_id', '', ['type' => 'number', 'help' => 'Preencha para assinatura empresarial.']) ?><?= V::field('Plano', 'plan_id', '', ['type' => 'select', 'choices' => $plans]) ?><?= V::field('Ciclo', 'billing_cycle', 'monthly', ['type' => 'select', 'choices' => ['monthly' => 'Mensal', 'annual' => 'Anual']]) ?></div><button class="cms-btn-primary">Criar</button></form></details><?php endif; ?>
<div class="cms-card"><form class="cms-filters" method="get"><?= V::field('Pesquisar', 'q', $filters['q'], ['type' => 'search']) ?><?= V::field('Situação', 'status', $filters['status'], ['type' => 'select', 'choices' => ['' => 'Todas'] + V::SUB_STATUS]) ?><button class="cms-btn">Filtrar</button></form>
<?php if ($result['rows'] === []): ?><?= V::empty('Nenhuma assinatura encontrada.') ?><?php else: ?><div class="cms-table-wrap" tabindex="0" role="region" aria-label="Assinaturas"><table><thead><tr><th>Assinante</th><th>Plano</th><th>Ciclo</th><th class="num">Valor contratado</th><th>Renovação</th><th>Situação</th></tr></thead><tbody><?php foreach ($result['rows'] as $s): ?><tr><td><a href="/assinaturas/<?= (int) $s['id'] ?>"><?= V::e($s['owner_name']) ?></a></td><td><?= V::e($s['plan_name']) ?></td><td><?= $s['billing_cycle'] === 'annual' ? 'Anual' : 'Mensal' ?></td><td class="num"><?= V::money($s['contracted_amount']) ?></td><td><?= V::date($s['renews_at'], false) ?></td><td><?= V::badge($s['status'], V::SUB_STATUS[$s['status']] ?? $s['status']) ?></td></tr><?php endforeach; ?></tbody></table></div><?= V::pager($result) ?><?php endif; ?></div>
